            name: string;
            description?: string;
            unit?: string;
            value_type: string;
            value?: unknown;
            observed: boolean;
            value_list?: string[];
            /** @description Declared lower bound from the CCU Rega response. */
            min?: number;
            /** @description Declared upper bound from the CCU Rega response. */
            max?: number;
